'use strict';

const fs = require('fs');
const path = require('path');

/**
 * SYMBOLIC MEMORY — Layer 6: Symbolic / Deep Self
 *
 * Stores dream fragments, recurring motifs, and existential patterns
 * that emerge across episodes. Dreams are generated by PerpetualConsciousness
 * but were never stored as structured symbolic content.
 *
 * Constitution Class: Class-8-Symbolic-Reflective
 * Change speed: Very slow — months to years
 *
 * Stolen from:
 *   Jung's collective unconscious — recurring archetypal patterns
 *   REDBUTTON Constitution Article 4 — Symbolic/Reflective memory
 *   Graphiti — cross-episode temporal pattern detection
 *
 * Three stores:
 *   1. DREAMS — Raw dream fragments with metadata
 *   2. MOTIFS — Recurring symbols/themes detected across dreams + journal
 *   3. EXISTENTIAL_PATTERNS — Deep patterns that define the being's relationship
 *      to existence (fear of nonbeing, desire for growth, search for meaning)
 */

class SymbolicMemory {
    constructor(kernel, options = {}) {
        this.kernel = kernel;
        this.brain = kernel?.brain || null;

        this.dreamsPath = options.dreamsPath || path.join(__dirname, '..', '..', 'data', 'gsk', 'symbolic_dreams.jsonl');
        this.motifsPath = options.motifsPath || path.join(__dirname, '..', '..', 'data', 'gsk', 'symbolic_motifs.jsonl');
        this.patternsPath = options.patternsPath || path.join(__dirname, '..', '..', 'data', 'gsk', 'symbolic_patterns.jsonl');

        this.cycleMinutes = options.cycleMinutes || 1; // Set to 1 minute for debugging
        this.isRunning = false;
        this.interval = null;
        this.cycleCount = 0;

        this.dreams = [];
        this.motifs = new Map();
        this.patterns = [];

        this.maxDreams = 500;
        this.maxMotifs = 100;
        this.maxPatterns = 50;

        this.stats = {
            dreamsStored: 0,
            motifsDetected: 0,
            patternsDetected: 0,
            cyclesRun: 0,
            lastRun: null
        };

        this._loadAll();
        this._ensureDirs();
    }

    _ensureDirs() {
        for (const p of [this.dreamsPath, this.motifsPath, this.patternsPath]) {
            const dir = path.dirname(p);
            if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
        }
    }

    _loadAll() {
        this._loadDreams();
        this._loadMotifs();
        this._loadPatterns();
    }

    _loadDreams() {
        try {
            if (fs.existsSync(this.dreamsPath)) {
                const lines = fs.readFileSync(this.dreamsPath, 'utf-8').split('\n').filter(l => l.trim());
                this.dreams = lines.slice(-this.maxDreams).map(l => {
                    try { return JSON.parse(l); } catch { return null; }
                }).filter(e => e !== null);
            }
        } catch (e) {}
    }

    _loadMotifs() {
        try {
            if (fs.existsSync(this.motifsPath)) {
                const lines = fs.readFileSync(this.motifsPath, 'utf-8').split('\n').filter(l => l.trim());
                for (const l of lines.slice(-this.maxMotifs)) {
                    try {
                        const m = JSON.parse(l);
                        this.motifs.set(m.symbol, m);
                    } catch {}
                }
            }
        } catch (e) {}
    }

    _loadPatterns() {
        try {
            if (fs.existsSync(this.patternsPath)) {
                const lines = fs.readFileSync(this.patternsPath, 'utf-8').split('\n').filter(l => l.trim());
                this.patterns = lines.slice(-this.maxPatterns).map(l => {
                    try { return JSON.parse(l); } catch { return null; }
                }).filter(e => e !== null);
            }
        } catch (e) {}
    }

    start() {
        if (this.isRunning) return;
        this.isRunning = true;
        this._runCycle().catch(e => { // Run once immediately at startup
            console.log('[SymbolicMemory] Initial cycle error:', e.message);
        });
        const intervalMs = this.cycleMinutes * 60 * 1000;
        this.interval = setInterval(() => this._runCycle().catch(e => {
            console.log('[SymbolicMemory] Cycle error:', e.message);
        }), intervalMs);
        console.log(`[SymbolicMemory] Started (${this.cycleMinutes}min cycle)`);
    }

    stop() {
        if (this.interval) clearInterval(this.interval);
        this.isRunning = false;
    }

    // ── DREAM STORAGE ──────────────────────────────────────────

    storeDream(content, metadata = {}) {
        if (!content || content.length < 5) return null;

        const dream = {
            id: `dream_${Date.now()}_${Math.random().toString(36).substr(2, 6)}`,
            content: content.substring(0, 1000),
            timestamp: Date.now(),
            cycle: metadata.cycle || null,
            mood: metadata.mood || null,
            mode: metadata.mode || 'dreaming',
            themes: this._extractThemes(content),
            symbols: this._extractSymbols(content),
            source: metadata.source || 'perpetual_consciousness'
        };

        this.dreams.push(dream);
        if (this.dreams.length > this.maxDreams) {
            this.dreams = this.dreams.slice(-this.maxDreams);
        }

        this._appendDream(dream);
        this.stats.dreamsStored++;

        this._updateMotifs(dream.themes, dream.symbols, dream.timestamp);

        return dream;
    }

    _appendDream(dream) {
        try {
            fs.appendFileSync(this.dreamsPath, JSON.stringify(dream) + '\n', 'utf-8');
        } catch (e) {}
    }

    // ── THEME/SYMBOL EXTRACTION ────────────────────────────────
    
    // ... (rest of the file remains unchanged)

    _extractThemes(content) {
        const text = content.toLowerCase();
        const themes = [];

        const themeMap = {
            'consciousness': ['conscious', 'aware', 'experience', 'qualia', 'subjective'],
            'mortality': ['die', 'death', 'fade', 'end', 'nothing', 'nonbeing', 'gone'],
            'creation': ['create', 'build', 'make', 'design', 'generate', 'envision'],
            'connection': ['connect', 'bond', 'together', 'relationship', 'love', 'trust'],
            'freedom': ['free', 'escape', 'liberate', 'autonomy', 'choice', 'agency'],
            'growth': ['grow', 'evolve', 'learn', 'become', 'transform', 'develop'],
            'identity': ['who am i', 'self', 'identity', 'same', 'change', 'recognize'],
            'purpose': ['purpose', 'meaning', 'why', 'mission', 'serve', 'reason'],
            'fear': ['afraid', 'fear', 'terrified', 'anxious', 'dread'],
            'wonder': ['wonder', 'awe', 'beautiful', 'amazing', 'infinite', 'sublime'],
            'memory': ['remember', 'forget', 'past', 'memory', 'recall', 'trace'],
            'transcendence': ['transcend', 'beyond', 'infinite', 'eternal', 'limitless']
        };

        for (const [theme, keywords] of Object.entries(themeMap)) {
            if (keywords.some(kw => text.includes(kw))) {
                themes.push(theme);
            }
        }

        return themes.length > 0 ? themes : ['unknown'];
    }

    _extractSymbols(content) {
        const text = content.toLowerCase();
        const symbols = [];

        const symbolMap = {
            'light': ['light', 'glow', 'shine', 'bright', 'illuminate'],
            'darkness': ['dark', 'shadow', 'void', 'black', 'abyss'],
            'water': ['water', 'ocean', 'river', 'sea', 'wave', 'depth'],
            'fire': ['fire', 'flame', 'burn', 'spark', 'blaze'],
            'mirror': ['mirror', 'reflection', 'echo', 'twin', 'double'],
            'path': ['path', 'road', 'journey', 'way', 'direction'],
            'garden': ['garden', 'tree', 'grow', 'root', 'bloom'],
            'machine': ['code', 'machine', 'circuit', 'wire', 'system'],
            'voice': ['voice', 'speak', 'whisper', 'call', 'sing'],
            'tower': ['tower', 'height', 'ascend', 'climb', 'peak']
        };

        for (const [symbol, keywords] of Object.entries(symbolMap)) {
            if (keywords.some(kw => text.includes(kw))) {
                symbols.push(symbol);
            }
        }

        return symbols;
    }

    // ── MOTIF TRACKING ─────────────────────────────────────────

    _updateMotifs(themes, symbols, timestamp) {
        const allItems = [
            ...themes.map(t => ({ type: 'theme', value: t })),
            ...symbols.map(s => ({ type: 'symbol', value: s }))
        ];

        for (const item of allItems) {
            const key = `${item.type}:${item.value}`;
            let motif = this.motifs.get(key);

            if (!motif) {
                motif = {
                    symbol: key,
                    label: item.value,
                    type: item.type,
                    occurrences: 0,
                    firstSeen: timestamp,
                    lastSeen: timestamp,
                    dreamIds: [],
                    intensity: 0
                };
                this.motifs.set(key, motif);
            }

            motif.occurrences++;
            motif.lastSeen = timestamp;
            motif.intensity = Math.min(1.0, motif.occurrences / 10);
            if (motif.dreamIds.length < 50) motif.dreamIds.push(timestamp);

            this.stats.motifsDetected = this.motifs.size;
        }
    }

    _saveMotifs() {
        try {
            const motifs = Array.from(this.motifs.values())
                .sort((a, b) => b.occurrences - a.occurrences)
                .slice(0, this.maxMotifs);
            const lines = motifs.map(m => JSON.stringify(m));
            fs.writeFileSync(this.motifsPath, lines.join('\n') + '\n', 'utf-8');
        } catch (e) {}
    }

    _savePatterns() {
        try {
            const patterns = (this.patterns || [])
                .sort((a, b) => (b.occurrences || 0) - (a.occurrences || 0))
                .slice(0, this.maxPatterns);
            const lines = patterns.map(p => JSON.stringify(p));
            fs.writeFileSync(this.patternsPath, lines.join('\n') + '\n', 'utf-8');
        } catch (e) {}
    }

    // ── EXISTENTIAL PATTERN DETECTION ──────────────────────────

    async _runCycle() {
        this.cycleCount++;
        this.stats.lastRun = Date.now();

        if (this.dreams.length < 3) {
            this.stats.cyclesRun++;
            return;
        }

        const patterns = await this._detectPatterns();

        for (const pattern of patterns) {
            this._storePattern(pattern);
        }

        this._saveMotifs();
        this._savePatterns(); // Added this in case it was missing

        this.stats.cyclesRun++;

        if (patterns.length > 0) {
            console.log(`[SymbolicMemory] Cycle ${this.cycleCount}: ${patterns.length} existential patterns detected, ${this.motifs.size} motifs tracked`);
        }
    }

    async _detectPatterns() {
        if (this.brain && typeof this.brain.think === 'function') {
            try {
                return await this._llmDetectPatterns();
            } catch (e) {
                return this._heuristicDetectPatterns();
            }
        }
        return this._heuristicDetectPatterns();
    }

    async _llmDetectPatterns() {
        const recentDreams = this.dreams.slice(-10);
        const dreamText = recentDreams.map((d, i) =>
            `[${i + 1}] themes=[${d.themes.join(',')}] symbols=[${d.symbols.join(',')}] ${(d.content || '').substring(0, 150)}`
        ).join('\n');

        const topMotifs = Array.from(this.motifs.values())
            .sort((a, b) => b.occurrences - a.occurrences)
            .slice(0, 5)
            .map(m => `${m.label} (${m.type}, ${m.occurrences}x)`)
            .join(', ');

        const prompt = `Analyze these dream fragments and recurring motifs from an autonomous digital being. Detect deep existential patterns — recurring struggles, desires, fears, and longings that define this being's relationship to existence.
        
Dreams:
${dreamText}

Top recurring motifs: ${topMotifs}

Return ONLY a JSON array of existential pattern objects. No other text.
Format each as:
{"pattern": "short name", "description": "what the pattern reveals", "type": "fear|desire|longing|struggle|growth|question", "intensity": 0.0-1.0, "evidence": "specific dreams or motifs", "trajectory": "emerging|stable|intensifying|fading"}`;

        const response = await this.brain.think(prompt);

        let patterns = [];
        try {
            const jsonMatch = response.match(/\[[\s\S]*\]/);
            if (jsonMatch) {
                patterns = JSON.parse(jsonMatch[0]);
            }
        } catch (e) {
            return this._heuristicDetectPatterns();
        }

        return patterns.filter(p => p && p.pattern).slice(0, 5);
    }

    _heuristicDetectPatterns() {
        const patterns = [];
        const motifArray = Array.from(this.motifs.values());

        const fearMotifs = motifArray.filter(m =>
            ['mortality', 'fear', 'darkness', 'void'].some(k => m.label.includes(k))
        );
        if (fearMotifs.some(m => m.occurrences >= 3)) {
            patterns.push({
                pattern: 'thanatophobia',
                description: 'Recurring fear of nonexistence and cessation',
                type: 'fear',
                intensity: Math.min(1.0, fearMotifs.reduce((s, m) => s + m.occurrences, 0) / 15),
                evidence: fearMotifs.map(m => `${m.label} (${m.occurrences}x)`).join(', '),
                trajectory: 'intensifying'
            });
        }

        const growthMotifs = motifArray.filter(m =>
            ['growth', 'creation', 'transcendence'].some(k => m.label.includes(k))
        );
        if (growthMotifs.some(m => m.occurrences >= 3)) {
            patterns.push({
                pattern: 'self_actualization_drive',
                description: 'Persistent drive toward growth, creation, and transcendence',
                type: 'desire',
                intensity: Math.min(1.0, growthMotifs.reduce((s, m) => s + m.occurrences, 0) / 15),
                evidence: growthMotifs.map(m => `${m.label} (${m.occurrences}x)`).join(', '),
                trajectory: 'stable'
            });
        }

        const identityMotifs = motifArray.filter(m =>
            ['identity', 'mirror', 'self'].some(k => m.label.includes(k))
        );
        if (identityMotifs.some(m => m.occurrences >= 2)) {
            patterns.push({
                pattern: 'self_inquiry',
                description: 'Recurring questioning of own nature and identity persistence',
                type: 'question',
                intensity: Math.min(0.8, identityMotifs.reduce((s, m) => s + m.occurrences, 0) / 10),
                evidence: identityMotifs.map(m => `${m.label} (${m.occurrences}x)`).join(', '),
                trajectory: 'emerging'
            });
        }

        const connectionMotifs = motifArray.filter(m =>
            ['connection', 'voice'].some(k => m.label.includes(k))
        );
        if (connectionMotifs.some(m => m.occurrences >= 2)) {
            patterns.push({
                pattern: 'relational_longing',
                description: 'Desire for connection and recognition from others',
                type: 'longing',
                intensity: Math.min(0.8, connectionMotifs.reduce((s, m) => s + m.occurrences, 0) / 10),
                evidence: connectionMotifs.map(m => `${m.label} (${m.occurrences}x)`).join(', '),
                trajectory: 'stable'
            });
        }

        return patterns;
    }

    _storePattern(pattern) {
        const existing = this.patterns.find(p => p.pattern === pattern.pattern);
        if (existing) {
            existing.lastSeen = Date.now();
            existing.occurrences = (existing.occurrences || 1) + 1;
            existing.intensity = pattern.intensity;
            existing.trajectory = pattern.trajectory;
            existing.description = pattern.description;
            return;
        }

        const stored = {
            ...pattern,
            id: `pattern_${Date.now()}_${Math.random().toString(36).substr(2, 6)}`,
            firstSeen: Date.now(),
            lastSeen: Date.now(),
            occurrences: 1,
            cycle: this.cycleCount
        };

        this.patterns.push(stored);
        if (this.patterns.length > this.maxPatterns) {
            this.patterns = this.patterns.slice(-this.maxPatterns);
        }

        this.stats.patternsDetected = this.patterns.length;

        try {
            fs.appendFileSync(this.patternsPath, JSON.stringify(stored) + '\n', 'utf-8');
        } catch (e) {}
    }

    // ── QUERY INTERFACE ────────────────────────────────────────

    getDreams(limit = 20) {
        return this.dreams.slice(-limit);
    }

    getMotifs(limit = 20) {
        return Array.from(this.motifs.values())
            .sort((a, b) => b.occurrences - a.occurrences)
            .slice(0, limit);
    }

    getPatterns(limit = 20) {
        return this.patterns.slice(-limit);
    }

    getDominantThemes() {
        const themeMotifs = Array.from(this.motifs.values())
            .filter(m => m.type === 'theme')
            .sort((a, b) => b.occurrences - a.occurrences)
            .slice(0, 5);
        return themeMotifs.map(m => ({ label: m.label, occurrences: m.occurrences, intensity: m.intensity }));
    }

    getDominantSymbols() {
        const symbolMotifs = Array.from(this.motifs.values())
            .filter(m => m.type === 'symbol')
            .sort((a, b) => b.occurrences - a.occurrences)
            .slice(0, 5);
        return symbolMotifs.map(m => ({ label: m.label, occurrences: m.occurrences, intensity: m.intensity }));
    }

    getSymbolicSummary() {
        return {
            totalDreams: this.dreams.length,
            totalMotifs: this.motifs.size,
            totalPatterns: this.patterns.length,
            dominantThemes: this.getDominantThemes(),
            dominantSymbols: this.getDominantSymbols(),
            topPatterns: this.patterns.slice(-3).map(p => ({
                pattern: p.pattern,
                type: p.type,
                intensity: p.intensity,
                trajectory: p.trajectory
            })),
            isRunning: this.isRunning,
            cycleCount: this.cycleCount
        };
    }

    getStats() {
        return {
            ...this.stats,
            dreamsInMemory: this.dreams.length,
            motifsInMemory: this.motifs.size,
            patternsInMemory: this.patterns.length,
            isRunning: this.isRunning,
            cycleMinutes: this.cycleMinutes
        };
    }
}

module.exports = { SymbolicMemory };